// UpdateBookingType is the resolver for the updateBookingType field.
func (r *mutationResolver) UpdateBookingType(ctx context.Context, typeArg model.BookingType) (*model.BookingType, error) {
	serviceIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get service ID: %v", err)
	}

	// Parse the UUID from the serviceID string
	serviceUUID, err := uuid.Parse(*serviceIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid service ID: %w", err)
	}

	// Find the service by ID
	var service model.Service
	if err := r.DB.Where("id = ?", serviceUUID).First(&service).Error; err != nil {
		if errors.Is(err, gorm.ErrRecordNotFound) {
			return nil, fmt.Errorf("service not found with ID %s", *serviceIDStr)
		}
		return nil, fmt.Errorf("failed to fetch service: %w", err)
	}

	// Create a map to track existing booking types
	bookTypeSet := make(map[string]bool)
	for _, existingType := range service.BookTypes {
		bookTypeSet[existingType] = true
	}

	// Toggle the booking type
	btStr := typeArg.String()
	if bookTypeSet[btStr] {
		// Remove if it exists
		delete(bookTypeSet, btStr)
	} else {
		// Add if it doesn't exist
		bookTypeSet[btStr] = true
	}

	// Convert the map back to pq.StringArray
	updatedBookTypes := pq.StringArray{}
	for bookType := range bookTypeSet {
		updatedBookTypes = append(updatedBookTypes, bookType)
	}
	service.BookTypes = updatedBookTypes

	// Save the updated service to the database
	if err := r.DB.Save(&service).Error; err != nil {
		return nil, fmt.Errorf("failed to update booking types: %w", err)
	}

	// Return response with updated booking types
	return &typeArg, nil
}

// CreateGallery is the resolver for the createGallery field.
func (r *mutationResolver) CreateGallery(ctx context.Context, files []*graphql.Upload, input model.GalleryProfessionInput) (*model.GalleryProfession, error) {
	// Retrieve the service ID from the context
	serviceIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get service ID: %v", err)
	}

	// Parse the UUID from string
	serviceID, err := uuid.Parse(*serviceIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid service ID: %w", err)
	}

	// Find the service to get the name for bucket generation
	var service model.Service
	if err := r.DB.Where("id = ?", serviceID).First(&service).Error; err != nil {
		return nil, fmt.Errorf("failed to find service: %w", err)
	}

	bucketName := fmt.Sprintf("service-%s-bucket", serviceID)

	log.Printf("Gallery bucket name: %s", bucketName)

	// Ensure the bucket exists in MinIO
	if err := helper.CreateBucketInMinio(ctx, r.MinIOClient, bucketName); err != nil {
		return nil, err
	}

	// Upload each file and store the URLs as pq.StringArray
	var galleryURLs pq.StringArray

	// Upload each file and store the URLs
	for _, file := range files {
		// Generate a unique filename with a prefix for galleries
		// filename := fmt.Sprintf("gallery-%d-%s", i, uuid.New().String()[:8])
		fileURL, err := helper.UploadFileToMinio(ctx, r.MinIOClient, bucketName, "gallery", file)
		if err != nil {
			return nil, fmt.Errorf("failed to upload file %s: %v", file.Filename, err)
		}
		galleryURLs = append(galleryURLs, fileURL)
	}

	// Process categories into pq.StringArray
	var categories pq.StringArray
	if input.Categories != nil {
		for _, catPtr := range input.Categories {
			if catPtr != nil {
				categories = append(categories, *catPtr)
			}
		}
	}

	// Create new gallery profession object
	gallery := model.GalleryProfession{
		ServiceID:  serviceIDStr,
		ImageUrls:  galleryURLs,
		Categories: categories,
	}

	// Add title if provided
	if input.Title != nil {
		gallery.Title = input.Title
	}

	// Add description if provided
	if input.Description != nil {
		gallery.Description = input.Description
	}

	// Save to database
	if err := r.DB.Create(&gallery).Error; err != nil {
		return nil, fmt.Errorf("failed to save gallery: %w", err)
	}

	return &gallery, nil
}

// UpdateGallery is the resolver for the updateGallery field.
func (r *mutationResolver) UpdateGallery(ctx context.Context, galleryID string, files []*graphql.Upload, input model.GalleryProfessionInput, removeURL []*string) (*model.GalleryProfession, error) {
	// Check if gallery ID is provided
	if galleryID == "" {
		return nil, fmt.Errorf("gallery ID is required for update")
	}

	// Parse the gallery ID
	parsedGalleryID, err := uuid.Parse(galleryID)
	if err != nil {
		return nil, fmt.Errorf("invalid gallery ID: %w", err)
	}

	// Get the service ID from context for authorization
	serviceIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get service ID: %v", err)
	}

	// Find the existing gallery
	var gallery model.GalleryProfession
	if err := r.DB.Where("id = ?", parsedGalleryID).First(&gallery).Error; err != nil {
		if errors.Is(err, gorm.ErrRecordNotFound) {
			return nil, fmt.Errorf("gallery not found with ID: %s", galleryID)
		}
		return nil, fmt.Errorf("failed to fetch gallery: %w", err)
	}

	// Verify the gallery belongs to the authenticated service
	if gallery.ServiceID == nil || *gallery.ServiceID != *serviceIDStr {
		return nil, fmt.Errorf("unauthorized: gallery does not belong to this service")
	}

	// Find the service to get the name for bucket generation
	var service model.Service
	serviceID, err := uuid.Parse(*serviceIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid service ID: %w", err)
	}

	if err := r.DB.Where("id = ?", serviceID).First(&service).Error; err != nil {
		return nil, fmt.Errorf("failed to find service: %w", err)
	}

	// Generate bucket name using the same pattern as in UpdateService
	bucketName := fmt.Sprintf("service-%s-bucket", serviceID)

	// Track whether any updates are made
	var updateNeeded bool

	// Update title if provided
	if input.Title != nil && (gallery.Title == nil || *gallery.Title != *input.Title) {
		gallery.Title = input.Title
		updateNeeded = true
	}

	// Update description if provided
	if input.Description != nil && (gallery.Description == nil || *gallery.Description != *input.Description) {
		gallery.Description = input.Description
		updateNeeded = true
	}

	// Update categories if provided
	if input.Categories != nil {
		// Convert input categories to a slice of strings for comparison
		newCategories := make([]string, 0)
		for _, catPtr := range input.Categories {
			if catPtr != nil {
				newCategories = append(newCategories, *catPtr)
			}
		}

		// Convert existing categories to a comparable format
		existingCategories := []string(gallery.Categories)

		// Check if categories have changed
		if !reflect.DeepEqual(newCategories, existingCategories) {
			// Create a new pq.StringArray from the input categories
			var categories pq.StringArray
			for _, catPtr := range input.Categories {
				if catPtr != nil {
					categories = append(categories, *catPtr)
				}
			}
			gallery.Categories = categories
			updateNeeded = true
		}
	}

	// Process new file uploads if any
	if len(files) > 0 {
		// Ensure bucket exists
		if err := helper.CreateBucketInMinio(ctx, r.MinIOClient, bucketName); err != nil {
			return nil, err
		}

		// Upload new files
		var newImageURLs []string
		for _, file := range files {
			// Generate a unique filename with a prefix for galleries
			// filename := fmt.Sprintf("gallery-%s", uuid.New().String()[:8])
			fileURL, err := helper.UploadFileToMinio(ctx, r.MinIOClient, bucketName, "gallery", file)
			if err != nil {
				return nil, fmt.Errorf("failed to upload file %s: %v", file.Filename, err)
			}
			newImageURLs = append(newImageURLs, fileURL)
		}

		// Handle image URLs update
		if input.ImageUrls != nil {
			// If imageURLs is provided in input, use only those URLs (replacing all)
			var convertedURLs pq.StringArray
			for _, urlPtr := range input.ImageUrls {
				if urlPtr != nil {
					convertedURLs = append(convertedURLs, *urlPtr)
				}
			}

			// Add newly uploaded images to the end
			for _, url := range newImageURLs {
				convertedURLs = append(convertedURLs, url)
			}

			gallery.ImageUrls = convertedURLs
		} else {
			// Keep existing URLs and add new ones
			existingURLs := gallery.ImageUrls

			// Add newly uploaded images
			for _, url := range newImageURLs {
				existingURLs = append(existingURLs, url)
			}

			gallery.ImageUrls = existingURLs
		}

		updateNeeded = true
	} else if input.ImageUrls != nil {
		// If no new files but imageUrls is provided, update to only those URLs
		var convertedURLs pq.StringArray
		for _, urlPtr := range input.ImageUrls {
			if urlPtr != nil {
				convertedURLs = append(convertedURLs, *urlPtr)
			}
		}
		gallery.ImageUrls = convertedURLs
		updateNeeded = true
	}
	// After processing new file uploads but before saving to the database
	// Handle URL removal if specified
	if len(removeURL) > 0 {
		// Create a map for quick lookup of URLs to remove
		urlsToRemove := make(map[string]bool)
		var keysToDelete []string

		for _, url := range removeURL {
			if url != nil {
				urlsToRemove[*url] = true
				keysToDelete = append(keysToDelete, *url)
			}
		}
		// Delete from MinIO
		helper.DeleteObjectsFromMinio(ctx, r.MinIOClient, bucketName, keysToDelete)
		// Filter out the URLs that need to be removed
		var filteredURLs pq.StringArray
		for _, url := range gallery.ImageUrls {
			if !urlsToRemove[url] {
				filteredURLs = append(filteredURLs, url)
			}
		}

		gallery.ImageUrls = filteredURLs
		updateNeeded = true
	}
	// Update timestamp
	if updateNeeded {

		// Save changes to database
		if err := r.DB.Save(&gallery).Error; err != nil {
			return nil, fmt.Errorf("failed to update gallery: %w", err)
		}
	}

	return &gallery, nil
}

// DeleteGallery is the resolver for the deleteGallery field.
func (r *mutationResolver) DeleteGallery(ctx context.Context, id string) (*bool, error) {
	// Get the service ID from context for authorization
	serviceIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get service ID: %v", err)
	}

	// Parse the gallery ID
	galleryID, err := uuid.Parse(id)
	if err != nil {
		return nil, fmt.Errorf("invalid gallery ID: %w", err)
	}

	// Find the gallery to verify ownership and get image URLs for cleanup
	var gallery model.GalleryProfession
	if err := r.DB.Where("id = ? AND service_id = ?", galleryID, serviceIDStr).First(&gallery).Error; err != nil {
		if errors.Is(err, gorm.ErrRecordNotFound) {
			return nil, fmt.Errorf("gallery not found with ID: %s or it does not belong to the service", galleryID)
		}
		return nil, fmt.Errorf("failed to fetch gallery: %w", err)
	}
	// Delete images from MinIO using the image URLs directly
	if gallery.ImageUrls != nil && len(gallery.ImageUrls) > 0 {
		bucketName := fmt.Sprintf("service-%s-bucket", *serviceIDStr)

		helper.DeleteObjectsFromMinio(ctx, r.MinIOClient, bucketName, gallery.ImageUrls)

	}
	// Delete the gallery from the database
	if err := r.DB.Delete(&gallery).Error; err != nil {
		return nil, fmt.Errorf("failed to delete gallery: %w", err)
	}

	// Return success
	result := true
	return &result, nil
}

