// CreateSocialMedia is the resolver for the createSocialMedia field.
func (r *mutationResolver) CreateSocialMedia(ctx context.Context, input *model.SocialMediaInput) (*model.SocialMedia, error) {
	serviceIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get Service ID: %v", err)
	}

	serviceID, err := uuid.Parse(*serviceIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid Service ID: %w", err)
	}

	tx := r.DB.Begin()
	if tx.Error != nil {
		return nil, fmt.Errorf("failed to begin transaction: %v", tx.Error)
	}

	var existing model.SocialMedia
	result := tx.Where("service_id = ?", serviceID.String()).First(&existing)

	// Construct new entry
	newEntry := map[string]string{
		"name": input.Name,
		"icon": input.Icon,
		"link": input.Link,
	}

	if result.Error == nil {
		// Existing record found, update its JSON
		var socialArray []map[string]string
		if existing.SocialData != nil {
			if err := json.Unmarshal(*existing.SocialData, &socialArray); err != nil {
				tx.Rollback()
				return nil, fmt.Errorf("failed to unmarshal social data: %v", err)
			}
		}

		// Replace or append
		updated := false
		for i, entry := range socialArray {
			if entry["icon"] == input.Icon {
				socialArray[i] = newEntry
				updated = true
				break
			}
		}
		if !updated {
			socialArray = append(socialArray, newEntry)
		}

		updatedJSON, err := json.Marshal(socialArray)
		if err != nil {
			tx.Rollback()
			return nil, fmt.Errorf("failed to marshal updated social data: %v", err)
		}

		raw := json.RawMessage(updatedJSON)
		existing.SocialData = &raw

		if err := tx.Save(&existing).Error; err != nil {
			tx.Rollback()
			return nil, fmt.Errorf("failed to update social media: %v", err)
		}

		if err := tx.Commit().Error; err != nil {
			return nil, fmt.Errorf("failed to commit transaction: %v", err)
		}

		return &existing, nil
	}

	// No existing record — create a new one
	initialArray := []map[string]string{newEntry}
	initialJSON, err := json.Marshal(initialArray)
	if err != nil {
		tx.Rollback()
		return nil, fmt.Errorf("failed to marshal new social data: %v", err)
	}

	raw := json.RawMessage(initialJSON)
	newSocialMedia := &model.SocialMedia{
		ServiceID:  serviceID.String(),
		SocialData: &raw,
	}

	if err := tx.Create(newSocialMedia).Error; err != nil {
		tx.Rollback()
		return nil, fmt.Errorf("failed to create social media: %v", err)
	}

	if err := tx.Commit().Error; err != nil {
		return nil, fmt.Errorf("failed to commit transaction: %v", err)
	}

	return newSocialMedia, nil
}

// ReAssignRider is the resolver for the reAssignRider field.
func (r *mutationResolver) ReAssignRider(ctx context.Context, entityID *string, entityType *string, riderID *string) (*model.UsersInfor, error) {
	// Validate required parameters
	if entityID == nil || *entityID == "" {
		return nil, fmt.Errorf("entityID is required")
	}
	if entityType == nil || *entityType == "" {
		return nil, fmt.Errorf("entityType is required")
	}
	if riderID == nil || *riderID == "" {
		return nil, fmt.Errorf("riderID is required")
	}

	// Parse entity ID
	entityUUID, err := uuid.Parse(*entityID)
	if err != nil {
		return nil, fmt.Errorf("invalid entity ID: %w", err)
	}

	// Start a transaction
	tx := r.DB.Begin()
	if tx.Error != nil {
		return nil, fmt.Errorf("failed to begin transaction: %w", tx.Error)
	}
	defer func() {
		if r := recover(); r != nil {
			tx.Rollback()
		}
	}()

	// Create dependency struct for helper functions
	deps := &helper.ReassignRiderData{
		DB:          r.DB,
		GetUserInfo: r.Query().GetUserInfor,
	}

	var response *helper.ReassignRiderResponse

	switch strings.ToLower(*entityType) {
	case "order":
		response, err = helper.ReassignOrderRider(ctx, tx, entityUUID, *riderID, deps)
		if err != nil {
			tx.Rollback()
			return nil, fmt.Errorf("failed to reassign rider for order: %w", err)
		}

	case "booking":
		response, err = helper.ReassignBookingRider(ctx, tx, entityUUID, *riderID, deps)
		if err != nil {
			tx.Rollback()
			return nil, fmt.Errorf("failed to reassign rider for booking: %w", err)
		}

	default:
		tx.Rollback()
		return nil, fmt.Errorf("invalid entityType: %s. Must be 'order' or 'booking'", *entityType)
	}

	// Commit transaction
	if err := tx.Commit().Error; err != nil {
		return nil, fmt.Errorf("failed to commit transaction: %w", err)
	}

	// Log the successful reassignment
	log.Printf("Successfully reassigned %s %s from rider %v to rider %s",
		response.EntityType, response.EntityID, response.PreviousRiderID, response.Rider.ID)
	// 🔔 Push Notifications
	go func() {
		defer func() {
			if r := recover(); r != nil {
				log.Printf("Push notification panic: %v", r)
			}
		}()

		tag := fmt.Sprintf("reassign-%s", response.EntityID)
		url := fmt.Sprintf("/%ss/%s", strings.ToLower(response.EntityType), response.EntityID)

		// Notify the new rider
		payload := helper.NotificationPayload{
			Title: "New Assignment",
			Body:  fmt.Sprintf("You’ve been assigned a new %s", response.EntityType),
			Tag:   tag,
			URL:   url,
		}
		if err := helper.SendPushNotification(r.DB, response.Rider.ID, payload); err != nil {
			log.Printf("❌ Failed to notify new rider %s: %v", response.Rider.ID, err)
		} else {
			log.Printf("✅ Notification sent to new rider %s", response.Rider.ID)
		}

		// Notify the previous rider (if any)
		if response.PreviousRiderID != nil && *response.PreviousRiderID != "" {
			payload := helper.NotificationPayload{
				Title: "Assignment Removed",
				Body:  fmt.Sprintf("You’ve been unassigned from a %s", response.EntityType),
				Tag:   tag,
				URL:   url,
			}
			if err := helper.SendPushNotification(r.DB, *response.PreviousRiderID, payload); err != nil {
				log.Printf("❌ Failed to notify previous rider %s: %v", *response.PreviousRiderID, err)
			} else {
				log.Printf("✅ Notification sent to previous rider %s", *response.PreviousRiderID)
			}
		}
	}()
	// Return the assigned rider information
	return response.Rider, nil
}

