// GetAllCategoriesFromGallery is the resolver for the getAllCategoriesFromGallery field.
func (r *queryResolver) GetAllCategoriesFromGallery(ctx context.Context, serviceID string) ([]*string, error) {
	// Use a direct SQL query with a WHERE clause to filter by ServiceID
	rows, err := r.DB.Raw(`
		SELECT DISTINCT unnest(categories) AS category 
		FROM gallery_professions 
		WHERE categories IS NOT NULL AND service_id = ?`, serviceID).Rows()
	if err != nil {
		return nil, fmt.Errorf("failed to fetch categories: %v", err)
	}
	defer rows.Close()

	// Collect all unique categories
	var uniqueCategories []string
	for rows.Next() {
		var category string
		if err := rows.Scan(&category); err != nil {
			return nil, fmt.Errorf("failed to scan category: %v", err)
		}
		uniqueCategories = append(uniqueCategories, category)
	}

	// Convert []string to []*string
	result := make([]*string, len(uniqueCategories))
	for i, category := range uniqueCategories {
		category := category // Create a new variable to avoid pointer issues in the loop
		result[i] = &category
	}

	return result, nil
}

